# The roles officer adds used to send to Vector from code; now admin-editable rows.
HARD_CODED_VECTOR_ROLES = ["pledge/new member educator", "risk management chair"]


def seed_rules(apps, schema_editor):
    from core.models import NAT_OFFICERS

    VectorGroup = apps.get_model("trainings", "VectorGroup")
    for role in HARD_CODED_VECTOR_ROLES:
        VectorGroup.objects.get_or_create(code=role, defaults={"assign_to_roles": [role]})
    EdCourse = apps.get_model("trainings", "EdCourse")
    national = set(NAT_OFFICERS)
    for course in EdCourse.objects.all():
        if national <= set(course.assign_to_roles):
            course.assign_to_national_officers = True
            course.assign_to_roles = [role for role in course.assign_to_roles if role not in national]
            course.save(update_fields=["assign_to_national_officers", "assign_to_roles"])


def unseed_rules(apps, schema_editor):
    from core.models import NAT_OFFICERS

    EdCourse = apps.get_model("trainings", "EdCourse")
    for course in EdCourse.objects.filter(assign_to_national_officers=True):
        course.assign_to_roles = sorted(set(course.assign_to_roles) | set(NAT_OFFICERS))
        course.save(update_fields=["assign_to_roles"])


